//! Minimal IDNA-style helpers, ported from the C++ `idna.hpp` header.
//!
//! The C++ original stores domains in `std::string`, which is a plain byte
//! container: it never decodes UTF-8, and its case conversions only touch
//! ASCII. Every function here therefore works on `[u8]` rather than `str`, so
//! UTF-8 (and even invalid UTF-8) input flows through byte for byte.

pub mod convert;
pub mod text;
pub mod validate;

pub use convert::{punycode_decode, punycode_encode, to_ascii, to_unicode};
pub use text::{count_labels, extract_tld, normalize, to_lower};
pub use validate::{is_ascii_domain, is_idn_domain, is_valid_domain, is_valid_label};

