//! Conversions between the unicode and ASCII-compatible-encoding forms.

use super::text::to_lower;

/// The ACE prefix that marks an encoded label.
pub const ACE_PREFIX: &[u8] = b"xn--";

/// Encodes a domain to its ASCII-compatible form: lowercased and prefixed.
pub fn to_ascii(domain: &[u8]) -> Vec<u8> {
    let mut encoded = ACE_PREFIX.to_vec();
    encoded.extend_from_slice(&to_lower(domain));
    encoded
}

/// Decodes an ASCII-compatible domain back to its unicode form.
pub fn to_unicode(domain: &[u8]) -> Vec<u8> {
    strip_ace_prefix(domain).to_vec()
}

/// Punycode-encodes `input`, keeping its case intact.
pub fn punycode_encode(input: &[u8]) -> Vec<u8> {
    let mut encoded = ACE_PREFIX.to_vec();
    encoded.extend_from_slice(input);
    encoded
}

/// Punycode-decodes `input`, undoing [`punycode_encode`].
pub fn punycode_decode(input: &[u8]) -> Vec<u8> {
    strip_ace_prefix(input).to_vec()
}

/// Drops one leading ACE prefix; leaves unprefixed input untouched.
fn strip_ace_prefix(input: &[u8]) -> &[u8] {
    match input.strip_prefix(ACE_PREFIX) {
        Some(rest) => rest,
        None => input,
    }
}

