//! Case folding and label inspection helpers.

/// Lowercases the ASCII letters in `input`, leaving every other byte alone.
pub fn to_lower(input: &[u8]) -> Vec<u8> {
    input.iter().map(|byte| byte.to_ascii_lowercase()).collect()
}

/// Normalizes a domain to its canonical form.
pub fn normalize(domain: &[u8]) -> Vec<u8> {
    to_lower(domain)
}

/// Returns the top-level label: everything after the last dot, or the whole
/// domain when there is no dot at all.
pub fn extract_tld(domain: &[u8]) -> Vec<u8> {
    match domain.iter().rposition(|&byte| byte == b'.') {
        Some(last_dot) => domain[last_dot + 1..].to_vec(),
        None => domain.to_vec(),
    }
}

/// Counts the dot-separated labels in `domain`, empty labels included.
pub fn count_labels(domain: &[u8]) -> i32 {
    let dots = domain.iter().filter(|&&byte| byte == b'.').count();
    (dots + 1) as i32
}

