//! Domain and label validity checks.

/// Longest accepted domain, in bytes.
pub const MAX_DOMAIN_LEN: usize = 255;

/// Longest accepted single label, in bytes.
pub const MAX_LABEL_LEN: usize = 63;

/// Reports whether `domain` is non-empty and within the length limit.
pub fn is_valid_domain(domain: &[u8]) -> bool {
    !domain.is_empty() && domain.len() <= MAX_DOMAIN_LEN
}

/// Reports whether `label` is non-empty, short enough, and free of leading or
/// trailing hyphens.
pub fn is_valid_label(label: &[u8]) -> bool {
    !label.is_empty()
        && label.len() <= MAX_LABEL_LEN
        && label[0] != b'-'
        && label[label.len() - 1] != b'-'
}

/// Reports whether `domain` is pure ASCII.
pub fn is_ascii_domain(domain: &[u8]) -> bool {
    domain.is_ascii()
}

/// Reports whether `domain` carries any non-ASCII byte, i.e. needs encoding.
pub fn is_idn_domain(domain: &[u8]) -> bool {
    !domain.is_ascii()
}

