//! Raw-byte access to the command line.

/// Returns the command-line arguments as raw bytes, `argv[0]` included.
///
/// `std::env::args()` panics on arguments that are not valid UTF-8, whereas the
/// C++ driver hands whatever bytes `argv` holds straight to `std::string`. Go
/// through `args_os` so that odd input survives the round trip unchanged.
#[cfg(unix)]
pub fn args_as_bytes() -> Vec<Vec<u8>> {
    use std::os::unix::ffi::OsStrExt;

    std::env::args_os()
        .map(|arg| arg.as_os_str().as_bytes().to_vec())
        .collect()
}

#[cfg(not(unix))]
pub fn args_as_bytes() -> Vec<Vec<u8>> {
    std::env::args_os()
        .map(|arg| arg.to_string_lossy().into_owned().into_bytes())
        .collect()
}

